<div class="row g-3"><div class="col-xl-7"><div class="card"><div class="card-header"><strong>Historial de campañas</strong></div><div class="card-body notification-list"><?php foreach($items as $n):?><article class="priority-<?=e($n['priority'])?>"><span class="notification-icon"><i class="bi bi-bell"></i></span><div><strong><?=e($n['title'])?></strong><p><?=e($n['message'])?></p><small><?=e(format_datetime_es((string)$n['created_at']))?> · <?=e($n['audience_type'])?> · <?=e($n['recipients'])?> destinatario(s)</small></div><span class="badge text-bg-<?=e(status_badge((string)$n['status']))?>"><?=e(status_label((string)$n['status']))?></span></article><?php endforeach;?><?php if(!$items):?><div class="text-center text-body-secondary py-4">No hay campañas enviadas.</div><?php endif;?></div></div></div><?php if(can('notifications.manage')):?><div class="col-xl-5"><div class="card"><div class="card-header"><strong>Enviar notificación real</strong></div><div class="card-body"><form method="post" action="<?=url('create-notification')?>"><?=csrf_field()?><div class="mb-3"><label class="form-label">Título</label><input class="form-control" name="title" required></div><div class="mb-3"><label class="form-label">Mensaje</label><textarea class="form-control" name="message" rows="4" required></textarea></div><div class="row g-3"><div class="col-6"><label class="form-label">Prioridad</label><select class="form-select" name="priority"><option value="normal">Normal</option><option value="high">Alta</option><option value="critical">Crítica</option></select></div><div class="col-6"><label class="form-label">Audiencia</label><select class="form-select" name="audience"><option value="all">Todo el conjunto</option><option value="residents">Residentes</option></select></div></div><div class="alert alert-info mt-3 mb-0">Se generará una notificación dentro de la app para cada cuenta residente activa.</div><button class="btn btn-primary w-100 mt-3">Enviar a Property App</button></form></div></div></div><?php endif;?></div>
